"""Copy Python support files into MAM-simple/py-examples/."""

import os
import shutil

from mb_cmn import paths

_PY_DIR = paths.repo_root() / "py"


def _vendored_subdirs():
    """The subdirectories PYFILE_RELPATHS actually names, in first-named order.

    Derived rather than listed by hand, so that the directories emptied and the
    files copied cannot disagree. A hand-kept list named "ws" from 4b37c95 --
    which spelled it "pyws", renamed to "ws" by 198a6e3 -- until 2026-08-09,
    though no ws/ file was ever named here under either spelling, so every run
    recreated an empty py-examples/ws/ directory that Git did not report.
    """
    return tuple(dict.fromkeys(relpath.split("/")[0] for relpath in PYFILE_RELPATHS))


def copy_support_files():
    """Copy support files into the landed MAM-simple product."""
    mam_simple_pyex = MAM_SIMPLE_PYEX
    os.makedirs(mam_simple_pyex, exist_ok=True)  # keep: top dir has non-vendored files
    for subdir in _vendored_subdirs():
        subdir_path = f"{mam_simple_pyex}/{subdir}"
        if os.path.isdir(subdir_path):
            shutil.rmtree(subdir_path)
        os.makedirs(subdir_path)
    for pyfile_relpath in PYFILE_RELPATHS:
        src = os.path.join(_PY_DIR, pyfile_relpath)
        dst = f"{mam_simple_pyex}/{pyfile_relpath}"
        shutil.copy(src, dst)
    prov_path = f"{mam_simple_pyex}/provenance.md"
    with open(prov_path, "w", encoding="utf-8", newline="") as f:
        f.write(_PROVENANCE_MD)


